  assert.deepEqual(selectPaths(['main.ts', 'src/main.js', 'style.css'], '**/*.{ts,js}'), ['main.ts', 'src/main.js'])
  assert.deepEqual(selectPaths(['.private.ts', 'main.ts', 'src/.private.ts'], '.*.ts'), ['.private.ts'])
})
